# -*- coding: utf-8 -*-
"""E-SIGN / UETA consent, Customer Portal Terms of Use, Sub Portal / bid-site Terms of Use, Sub Portal privacy notice."""
from .lib import *

CHECK = "I agree to do business electronically with GrayCo Construction Services, LLC. I have read the disclosure above, and I can open and read it and PDF documents on the device I am using."

ESIGN = [
 ('h', 'What this is'),
 ('p', "GrayCo Construction Services, LLC (\"GrayCo\") would like to use electronic records and electronic signatures with you for your project. Federal law (the E-SIGN Act, 15 U.S.C. § 7001 et seq.) and the Uniform Electronic Transactions Acts of Tennessee, Mississippi and Arkansas let us do that only if you agree first. Please read this before you sign anything in the portal."),
 ('h', 'What you are agreeing to'),
 ('p', "You agree that GrayCo may give you, and you may sign and send back, these things electronically: proposals and estimates, contracts, change orders, work authorizations and directions to pay, lien waivers and notices, invoices and receipts, warranty certificates, completion and walkthrough papers, selections, and notices about your project. Your typed name (and any signature you draw) on a document in the portal is your electronic signature and has the same legal effect as a handwritten signature. GrayCo keeps a record of the date, time, device address (IP address) and what you signed."),
 ('p', "This consent applies to this project and to later projects and papers with GrayCo, until you withdraw it."),
 ('h', 'Your right to a paper copy'),
 ('p', "You have the right to receive any document on paper, free of charge. To ask for a paper copy, call " + PHONE + " or e-mail " + EMAIL + " and tell us which document you want and where to send it. You can also print or save any document you sign in the portal. Where the law requires a notice to be given to you in paper or in a particular form (for example the Notice of Cancellation, which GrayCo gives you in duplicate), GrayCo will give it to you in that form."),
 ('h', 'Your right to say no, and to withdraw your consent'),
 ('p', "You do not have to agree to do business electronically. If you do not agree, GrayCo will give you paper documents and sign them with you in person or by mail, and your price and your rights are the same. If you agree now, you may withdraw your consent at any time by calling " + PHONE + " or e-mailing " + EMAIL + " (or by writing to GrayCo, " + ADDR + "). Withdrawing consent does not affect any document you already signed electronically. It may delay your project because paper documents will have to be mailed or signed in person. There is no fee for withdrawing consent."),
 ('h', 'What you need'),
 ('li', ["A computer, tablet or phone with an internet connection.",
         "A current web browser (the latest two versions of Chrome, Safari, Edge or Firefox) with JavaScript and cookies turned on.",
         "A program that can open PDF files (such as the free Adobe Acrobat Reader, or the PDF viewer built into your phone or browser).",
         "An e-mail address and/or a mobile phone number that you can use to receive your personal portal link and your signed copies.",
         "A way to print or save PDF copies if you want them."]),
 ('p', "If our requirements change in a way that could keep you from opening your documents, we will tell you before the change and you may withdraw your consent without charge."),
 ('h', 'Keeping your information current'),
 ('p', "Tell GrayCo right away if your e-mail address, mobile number or mailing address changes so we can keep sending your documents to you."),
 ('h', 'Your copies'),
 ('p', "After you sign, a signed copy is stored in your portal and e-mailed to you. Keep a copy for your records."),
]

TOU_CUSTOMER = [
 ('p', "These Terms of Use apply to the GrayCo customer portal at portal.grayco-cs.com (the \"Portal\"). By signing in or using the Portal you agree to them. The Portal is run by " + GCO + ", " + ADDR + ". If you do not agree, do not use the Portal; call " + PHONE + " and we will work with you on paper."),
 ('h', '1. Who may use the Portal'),
 ('p', "The Portal is for GrayCo customers (and people a customer has told us may act for them) so they can see their own project. You may use it only for your own project. Your personal link and any sign-in code are private. Anyone who has your link can see and sign your project papers, so do not share it, forward it, or post it online. Tell us at once if you think someone else has it and we will turn it off and send a new one."),
 ('h', '2. What the Portal is'),
 ('p', "The Portal shows project updates, photos, schedules, documents, invoices and payments, and lets you sign papers, send messages and request service. It is a convenience. Your written contract, change orders and warranty control your work and your rights. Nothing in the Portal is legal, insurance or tax advice. If the Portal and your signed contract disagree, the signed contract controls."),
 ('h', '3. Electronic signatures and records'),
 ('p', "Before you sign a paper in the Portal you will be asked to agree to do business electronically (see the E-SIGN Disclosure and Consent). Your typed name and any signature you draw are your electronic signature. You may ask for any document on paper."),
 ('h', '4. Your responsibilities'),
 ('li', ["Give us true and current information and keep it up to date.",
         "Do not try to get into another customer's project, to test or probe the security of the Portal, to overload it, or to copy it with automated tools.",
         "Do not upload anything unlawful, harmful (such as viruses), or that you do not have the right to share.",
         "Use the message tool for project matters, not for emergencies. For an emergency call " + PHONE + "."]),
 ('h', '5. Photos and files'),
 ('p', "Project photos and documents shown in the Portal belong to GrayCo or to you, as the case may be, and are shown for your project. You may download and keep what is yours. What you upload or write in the Portal may be used by GrayCo to do the work, document it, and handle insurance, warranty and legal matters about your project. GrayCo will not post your photos publicly without your permission."),
 ('h', '6. Privacy and text messages'),
 ('p', "How we handle your information is described in our Privacy Policy (privacy.html). Texts about your job are sent only if you checked the separate Job texts box; promotional texts are only if you checked the separate, optional Offers box. Reply STOP to opt out. See the Text Message Consent page."),
 ('h', '7. Availability'),
 ('p', "We try to keep the Portal available but it may be down for maintenance or outside our control. We may change or stop any part of it. A document that must be given to you by a deadline will also be given another way if the Portal is unavailable."),
 ('h', '8. No warranty; limits on liability'),
 ('p', "<b>THE PORTAL IS PROVIDED \"AS IS\" AND \"AS AVAILABLE\". TO THE EXTENT THE LAW ALLOWS, GRAYCO IS NOT LIABLE FOR INDIRECT OR CONSEQUENTIAL DAMAGES FROM USING OR NOT BEING ABLE TO USE THE PORTAL.</b> This does not limit GrayCo's responsibility for its construction work under your contract and warranty, and it does not limit any right you have under law that cannot be waived."),
 ('h', '9. Ending access'),
 ('p', "We may suspend or end your access if you break these Terms or put the Portal or other customers at risk. When your project and warranty are finished, we may turn off your link; we keep your signed records as the law and our contract require."),
 ('h', '10. Changes'),
 ('p', "We may update these Terms. The date at the top shows the latest version. If you keep using the Portal after a change, you accept the new Terms. A change does not affect papers you already signed."),
 ('h', '11. Law and disputes'),
 ('p', "These Terms are governed by the law of the state where your project is located (Tennessee, Mississippi or Arkansas). Disagreements about the Portal itself are handled first by talking with us; disagreements about your construction project are handled as stated in your contract."),
 ('h', '12. Contact'),
 ('p', GCO + ", " + ADDR + " · " + PHONE + " · " + EMAIL + "."),
]

TOU_SUB = [
 ('p', "These Terms of Use apply to the GrayCo bid site (bids.grayco-cs.com), the Sub Portal inside the GrayCo CRM, and the GrayCo Portal for subcontractors and suppliers (together the \"Sub Portal\"). By creating an account, signing in or using the Sub Portal you agree to them on behalf of yourself and the company you represent. The Sub Portal is run by " + GCO + ", " + ADDR + " (\"GrayCo\")."),
 ('h', '1. Business use only; approval'),
 ('p', "The Sub Portal is for contractors, subcontractors, suppliers and their employees who do business with GrayCo. It is not for consumers. GrayCo approves each account and may refuse, suspend or end access at any time. You confirm that you have authority to bind your company."),
 ('h', '2. Your account'),
 ('p', "Keep your password, sign-in codes and links private. You are responsible for what is done with your account. Tell us at once if you think it was misused. Give accurate information and keep your W-9, insurance certificates, license information and contacts current."),
 ('h', '3. Bids and invitations'),
 ('p', "An invitation to bid is not a contract and does not promise work. GrayCo may reject any bid, waive informalities and award in the best interest of the project; the lowest bid is not necessarily accepted. Unless the invitation says otherwise, a bid stays open for 90 days. You bid at your own cost. A subcontract exists only when GrayCo and your company sign a subcontract (including the Master Subcontract Agreement and a signed Work Order or scope)."),
 ('h', '4. Plans, prices and confidential information'),
 ('p', "Plans, specifications, takeoffs, prices, customer information, access codes and other project information in the Sub Portal are confidential. Use them only to bid or perform work for GrayCo, do not copy or share them with anyone who does not need them, and delete or return them when asked. Access codes and customer information may be used only on the days and for the job you are scheduled on."),
 ('h', '5. Electronic signatures and records'),
 ('p', "When you sign a scope of work, work order, change order, lien waiver or other paper in the Sub Portal, you will be asked to agree to do business electronically (see the E-SIGN Disclosure and Consent). Your typed name and any signature you draw are your electronic signature. We record the time, device address and the version signed."),
 ('h', '6. Your uploads'),
 ('p', "You may upload documents, photos, bids, invoices and messages. You confirm they are yours to share, are accurate and are not unlawful. You give GrayCo permission to use them to evaluate bids, manage the work, pay you, document the project and resolve disputes. Job photos may be shared with the customer and the owner."),
 ('h', '7. Independent business'),
 ('p', "Using the Sub Portal does not make you or your workers GrayCo employees or give you authority to bind GrayCo. Your relationship with GrayCo is governed by your signed subcontract. You will not contact GrayCo's customers about price, billing or insurance claims, and you will not act as a public adjuster or promise any customer anything on GrayCo's behalf."),
 ('h', '8. Payments and tax records'),
 ('p', "Invoices you submit are paid under the payment rules in your signed subcontract. GrayCo may withhold payment until your W-9, current insurance certificate and any lien waiver required for the job are on file. GrayCo reports payments as required by law (for example on Form 1099)."),
 ('h', '9. Messages and text messages'),
 ('p', "Schedule, safety and job texts from GrayCo are sent to the number you gave us. Reply STOP to stop texts and HELP for help; message and data rates may apply. We send promotional texts only if you separately agree. Texts are not a condition of working with GrayCo, but we may need another way to reach you about schedules."),
 ('h', '10. Acceptable use'),
 ('p', "Do not break into or probe the Sub Portal, load it with automated tools, upload viruses or unlawful content, or use it to compete unfairly. Do not bid on or share another company's account."),
 ('h', '11. No warranty; limits on liability'),
 ('p', "<b>THE SUB PORTAL IS PROVIDED \"AS IS\" AND \"AS AVAILABLE\". TO THE EXTENT THE LAW ALLOWS, GRAYCO IS NOT LIABLE FOR LOST BIDS, LOST PROFITS OR INDIRECT OR CONSEQUENTIAL DAMAGES FROM USING OR NOT BEING ABLE TO USE THE SUB PORTAL.</b> Nothing here changes the payment or other rights in a signed subcontract."),
 ('h', '12. Changes and ending'),
 ('p', "We may change these Terms or the Sub Portal. The date at the top shows the latest version. We may end your access at any time. Terms that by their nature continue (confidentiality, uploads, limits on liability, law and disputes) survive."),
 ('h', '13. Law and disputes'),
 ('p', "These Terms are governed by Tennessee law. Disagreements about the Sub Portal itself are first handled by talking with us; disagreements about work or payment are handled under your signed subcontract. If there is no signed subcontract, the courts in Shelby County, Tennessee may hear the disagreement."),
 ('h', '14. Contact'),
 ('p', GCO + ", " + ADDR + " · " + PHONE + " · " + EMAIL + "."),
]

PRIVACY_SUB = [
 ('p', "This notice explains what information GrayCo Construction Services, LLC (\"GrayCo\", " + ADDR + ") collects through the GrayCo bid site, Sub Portal and GrayCo Portal for subcontractors and suppliers, and how we use and protect it. It supplements our general Privacy Policy (privacy.html)."),
 ('h', 'Information we collect'),
 ('li', ["<b>Account and company information:</b> company name, owner or contact names, phone, e-mail, address, trades, years in business, contractor license numbers, references.",
         "<b>Tax and payment information:</b> your W-9 (which may include an EIN or, for sole proprietors, a Social Security number), payment method and bank details you choose to give us, invoices and payment history.",
         "<b>Insurance and compliance documents:</b> certificates of insurance, workers' compensation information, signed agreements and lien waivers.",
         "<b>Bids and project information:</b> bids, scopes, prices, questions, schedule and availability, job photos and files you upload.",
         "<b>Technical information:</b> device and browser type, IP address, dates and times of sign-in and signing, and basic usage records, for security and to prove what was signed.",
         "<b>Messages:</b> messages and replies, including text messages you send or receive."]),
 ('h', 'How we use it'),
 ('li', ["To evaluate and award bids, set up and manage your subcontract, schedule work, and pay you.",
         "To meet legal and tax duties (for example Form 1099 reporting), insurance and license checks, and lien and payment-bond requirements.",
         "To keep the Sub Portal secure, prevent fraud, and keep records of signatures and consent.",
         "To communicate with you about jobs, schedules, safety and payments. Promotional texts only if you separately agree."]),
 ('h', 'Who sees it'),
 ('p', "Your information is available to GrayCo staff who need it. We share it only as needed with: the owner or general contractor on a project (for example your company name, insurance and lien waivers); our service providers that host the system, send e-mail and text messages, handle accounting and payments, and store files, under their own security terms; our insurers, lawyers, accountants and lenders; and government agencies when the law requires. We do not sell your personal information."),
 ('h', 'Sensitive information'),
 ('p', "We ask for your tax ID only on your W-9 or payment forms. Do not e-mail a full tax ID or bank account number; upload it in the Sub Portal or give it to the office. Access codes and customer contact details shown to you in the Sub Portal are for the job you are scheduled on only."),
 ('h', 'How long we keep it'),
 ('p', "We keep subcontract, payment, tax and insurance records for as long as needed for the work, warranty and lien periods and the legal and tax periods that apply (generally at least seven years), then delete or anonymize them."),
 ('h', 'Security'),
 ('p', "We use access controls, encrypted connections and approval steps to protect your information. No system is perfectly secure. Tell us right away if you think your account was misused."),
 ('h', 'Your choices'),
 ('p', "You can ask to see, correct or delete information we hold about you (we may need to keep some for legal or tax reasons), stop text messages by replying STOP, and ask us not to use your photos publicly. Call " + PHONE + " or e-mail " + EMAIL + ". If the law of your state gives you additional rights, we will honor them."),
 ('h', 'Children'),
 ('p', "The Sub Portal is for businesses and is not directed to children."),
 ('h', 'Changes and contact'),
 ('p', "We may update this notice; the date at the top shows the latest version. Questions: " + GCO + ", " + ADDR + " · " + PHONE + " · " + EMAIL + "."),
]

def build():
    doc('esign_consent', 'E-SIGN / UETA Consent — Agree to Do Business Electronically', 'Portal & Legal Notices', ALL, True,
        [('title', 'Consent to Do Business Electronically', 'E-SIGN Act (15 U.S.C. § 7001 et seq.) and the Tennessee, Mississippi and Arkansas Uniform Electronic Transactions Acts')] + [('box', "<b>Please read before you sign electronically.</b> Shown in the customer portal and the sub portal before any e-signature.")] + ESIGN +
        [('checks', [CHECK]), ('sigs', 'Customer / signer', GCO)], flags=[
         "Enforceability: portal signing is a typed name + optional drawn signature + one checkbox, with IP and time stored. Is that enforceable for contracts, change orders, work authorizations and waivers in TN, MS and AR (UETA: Tenn. Code Ann. § 47-10-101 et seq.; Miss. Code Ann. § 75-12-1 et seq.; Ark. Code Ann. § 25-32-101 et seq. — please verify cites)?",
         "E-SIGN consumer disclosure requirements (15 U.S.C. § 7001(c)) are covered: paper copies, withdrawal and effect, scope, hardware/software and updates, and a checkbox that reasonably demonstrates the ability to access the disclosure. Confirm the 'reasonably demonstrates' wording.",
         "Notice of Cancellation: the FTC rule and state acts require the notice in duplicate, in writing. We give a paper (or printable PDF) duplicate notice even to portal signers. Does counsel accept an electronic duplicate for customers who consented, or require paper?",
         "Texts 'set by staff' (staff-recorded consent) is outside this form; see the TCPA review item.",
         "Portal links are bearer links (anyone with the link can sign). Counsel: is a second factor required for signing high-value documents?",
         "Spanish: the sub portal is bilingual; this consent is English only for now. Counsel: do you want a certified Spanish translation before use with Spanish-speaking subs?"])
    doc('portal_tou', 'Customer Portal Terms of Use', 'Portal & Legal Notices', ALL, True,
        [('title', 'GrayCo Customer Portal — Terms of Use', 'portal.grayco-cs.com')] + TOU_CUSTOMER,
        flags=["Governing law is the project's state; counsel may prefer Tennessee for all portal disputes.",
               "No arbitration clause here (the contract already has one); confirm that avoiding a second dispute clause is the right call and that these terms do not conflict with the contract's.",
               "Photos clause: customers grant GrayCo permission to use uploads for the job; separate permission for marketing use is requested elsewhere. Confirm.",
               "Bearer-link security language (see E-SIGN flags)."])
    doc('subportal_tou', 'Sub Portal / Bid-Site Terms of Use', 'Portal & Legal Notices', ['commercial', 'residential', 'insurance'], False,
        [('title', 'GrayCo Sub Portal and Bid Site — Terms of Use', 'bids.grayco-cs.com and the GrayCo Portal for subs')] + TOU_SUB,
        flags=["Bid validity (90 days) is taken from the existing Invitation to Bid. Confirm.",
               "Independent-contractor language and the 'no contact with customers about price/billing/claims' rule: confirm enforceability and consistency with the Master Subcontract.",
               "Governing law and venue (Tennessee, Shelby County) differ from the project-state rule in the customer contract; confirm that is intended for portal use.",
               "Confidentiality of plans and customer information: counsel to confirm it is enough or needs a standalone NDA."])
    doc('subportal_privacy', 'Sub Portal / Bid-Site Privacy Notice', 'Portal & Legal Notices', ['commercial', 'residential', 'insurance'], False,
        [('title', 'GrayCo Sub Portal and Bid Site — Privacy Notice', 'How we handle subcontractor and supplier information')] + PRIVACY_SUB,
        flags=["State privacy laws: Tennessee's Information Protection Act (effective July 2025) and similar laws apply only to larger businesses; we believe GrayCo is below the thresholds but ask counsel to confirm. Mississippi and Arkansas have no comprehensive consumer privacy act that we found.",
               "We say we do not sell personal information. Confirm that matches how marketing tools and any data vendors are used.",
               "SSN/EIN handling and retention (7 years) — confirm retention period and breach-notice duties (Tenn. Code Ann. § 47-18-2107, Miss. Code Ann. § 75-24-29, Ark. Code Ann. § 4-110-101 et seq. — please verify cites)."])
build()
